package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/room") public class RoomController{private final RoomService s;public RoomController(RoomService s){this.s=s;}@PostMapping public ResponseEntity<RoomDTO> create(@Valid @RequestBody RoomDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<RoomDTO> all(){return s.all();}@GetMapping("/{id}") public RoomDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public RoomDTO update(@PathVariable Long id,@Valid @RequestBody RoomDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@GetMapping("/available") public List<RoomDTO> available(){return s.available();}}
